  /**
   * @return The number of rows updated.
   */
  public fun insertWarranty(
    id: String,
    productName: String,
    store: String,
    category: String,
    purchaseDateLabel: String,
    warrantyStatusLabel: String,
    urgencyDays: Long?,
    price: Double?,
    shape: String,
    warrantyEndDateLabel: String?,
  ): QueryResult<Long> {
    val result = driver.execute(-2_101_449_608, """
        |INSERT INTO warrantyEntity(id, productName, store, category, purchaseDateLabel, warrantyStatusLabel, urgencyDays, price, shape, warrantyEndDateLabel)
        |VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """.trimMargin(), 10) {
          bindString(0, id)
          bindString(1, productName)
          bindString(2, store)
          bindString(3, category)
          bindString(4, purchaseDateLabel)
          bindString(5, warrantyStatusLabel)
          bindLong(6, urgencyDays)
          bindDouble(7, price)
          bindString(8, shape)
          bindString(9, warrantyEndDateLabel)
        }
    notifyQueries(-2_101_449_608) { emit ->
