package org.example.project.db.shared

import app.cash.sqldelight.TransacterImpl
import app.cash.sqldelight.db.AfterVersion
import app.cash.sqldelight.db.QueryResult
import app.cash.sqldelight.db.SqlDriver
import app.cash.sqldelight.db.SqlSchema
import kotlin.Long
import kotlin.Unit
import kotlin.reflect.KClass
import org.example.project.db.WarrantyDatabase
import org.example.project.db.WarrantyQueries

internal val KClass<WarrantyDatabase>.schema: SqlSchema<QueryResult.Value<Unit>>
  get() = WarrantyDatabaseImpl.Schema

internal fun KClass<WarrantyDatabase>.newInstance(driver: SqlDriver): WarrantyDatabase =
    WarrantyDatabaseImpl(driver)

private class WarrantyDatabaseImpl(
  driver: SqlDriver,
) : TransacterImpl(driver),
    WarrantyDatabase {
  override val warrantyQueries: WarrantyQueries = WarrantyQueries(driver)

  public object Schema : SqlSchema<QueryResult.Value<Unit>> {
    override val version: Long
      get() = 1

    override fun create(driver: SqlDriver): QueryResult.Value<Unit> {
      driver.execute(null, """
          |CREATE TABLE warrantyEntity (
          |    id TEXT NOT NULL PRIMARY KEY,
          |    productName TEXT NOT NULL,
          |    store TEXT NOT NULL,
          |    category TEXT NOT NULL,
          |    purchaseDateLabel TEXT NOT NULL,
          |    warrantyStatusLabel TEXT NOT NULL,
          |    urgencyDays INTEGER,
          |    price REAL,
          |    shape TEXT NOT NULL,
          |    warrantyEndDateLabel TEXT
          |)
          """.trimMargin(), 0)
      driver.execute(null, """
          |CREATE TABLE policyEntity (
          |    id TEXT NOT NULL PRIMARY KEY,
          |    warrantyId TEXT NOT NULL,
          |    kind TEXT NOT NULL,
          |    title TEXT NOT NULL,
          |    provider TEXT,
          |    durationDays INTEGER,
          |    endEpochDay INTEGER,
          |    endDateLabel TEXT,
          |    notes TEXT,
          |    source TEXT NOT NULL
          |)
          """.trimMargin(), 0)
      return QueryResult.Unit
    }

    override fun migrate(
      driver: SqlDriver,
      oldVersion: Long,
      newVersion: Long,
      vararg callbacks: AfterVersion,
    ): QueryResult.Value<Unit> = QueryResult.Unit
  }
}
